<script setup>
import { ref, computed } from 'vue';
import { ArrowRight, RotateCcw, Check, X, Sparkles, Trophy, ExternalLink } from '@lucide/vue';
import { quizQuestions } from '../knowledge.js';
defineEmits(['navigate']);
const index=ref(0),answer=ref(null),submitted=ref(false),finished=ref(false),score=ref(0);
const current=computed(()=>quizQuestions[index.value]);
function submit(){if(answer.value===null||submitted.value)return;submitted.value=true;if(answer.value===current.value.answer)score.value++}
function next(){if(index.value===quizQuestions.length-1){finished.value=true;try{localStorage.setItem('xingyu-quiz-best',String(Math.max(Number(localStorage.getItem('xingyu-quiz-best')||0),score.value)))}catch{}}else{index.value++;answer.value=null;submitted.value=false}}
function restart(){index.value=0;answer.value=null;submitted.value=false;finished.value=false;score.value=0}
</script>
<template>
  <section class="page-shell quiz-shell"><div class="eyebrow">HOW WELL DO YOU KNOW THE UNIVERSE?</div><h1>天文挑战<span class="heading-dot">.</span></h1><p class="page-description">五个问题，一次小小的星际探险。</p><div v-if="finished" class="quiz-card result-card"><Trophy :size="52"/><div class="eyebrow">EXPLORATION COMPLETE</div><h2>{{score===5?'宇宙知识家，探索成功！':'好奇心，是最好的出发点。'}}</h2><div class="final-score">{{score*20}}<small> / 100</small></div><p>答对 {{score}} / {{quizQuestions.length}} 题。{{score===5?'把这份好奇带到下一个宇宙故事里吧。':'每一道题的解析，都在帮你读懂宇宙。'}}</p><div class="result-actions"><button class="button secondary" @click="restart"><RotateCcw :size="17"/> 再挑战一次</button><button class="button primary" @click="$emit('navigate','explore')">继续探索 </button></div></div><div v-else class="quiz-card"><div class="quiz-meta"><span>基础天文 · 单选题</span><span>0{{index+1}} <small>/ 0{{quizQuestions.length}}</small></span></div><div class="progress-track"><i :style="{width:`${(index+(submitted?1:0))/quizQuestions.length*100}%`}"></i></div><h2>{{current.question}}</h2><div class="quiz-options"><button v-for="(option,i) in current.options" :disabled="submitted" :class="{selected:answer===i,correct:submitted&&i===current.answer,incorrect:submitted&&i===answer&&i!==current.answer}" @click="answer=i"><span class="option-letter">{{String.fromCharCode(65+i)}}</span>{{option}}<Check v-if="submitted&&i===current.answer" :size="18"/><X v-else-if="submitted&&i===answer" :size="18"/></button></div><div v-if="submitted" class="quiz-analysis" role="status"><Sparkles :size="19"/><div><strong>{{answer===current.answer?'回答正确，继续保持好奇！':'接近答案了，一起看看原理。'}}</strong><p>{{current.analysis}}</p><a :href="current.source" target="_blank" rel="noopener noreferrer">NASA 资料来源 </a></div></div><div class="quiz-bottom"><small>{{submitted?'解析来自已整理的科普资料':'选择一个答案，再揭晓宇宙的秘密。'}}</small><button v-if="!submitted" class="button primary" :disabled="answer===null" @click="submit">确认答案 </button><button v-else class="button primary" @click="next">{{index===quizQuestions.length-1?'查看结果':'下一题'}} </button></div></div><p class="small-note">本版为固定题库与资料解析；AI 动态出题及解析将在模型接入后提供。</p></section>
</template>
